<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Ubuntu-like Desktop</title>
<style>
  * { box-sizing: border-box; }
  html, body {
    margin: 0; padding: 0; width: 100%; height: 100%;
    font-family: "Ubuntu", "Segoe UI", Arial, sans-serif;
    overflow: hidden;
  }
  #desktop {
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: radial-gradient(circle at 30% 20%, #4a2b5c, #2c0b3f 45%, #1a0a26 100%);
    color: #eee;
    user-select: none;
  }
  #top-bar {
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 28px;
    background: rgba(20, 10, 25, 0.85);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13px;
    color: #ddd;
    letter-spacing: 0.5px;
    border-bottom: 1px solid rgba(255,255,255,0.05);
    z-index: 5000;
  }
  #desktop-icons {
    position: absolute;
    top: 44px;
    left: 16px;
    display: flex;
    flex-direction: column;
    gap: 18px;
  }
  .desk-icon {
    width: 80px;
    text-align: center;
    font-size: 12px;
    color: #f0f0f0;
    text-shadow: 0 1px 3px rgba(0,0,0,0.8);
    cursor: pointer;
    padding: 8px 4px;
    border-radius: 6px;
  }
  .desk-icon:hover { background: rgba(255,255,255,0.08); }
  .desk-icon .glyph {
    font-size: 32px;
    display: block;
    margin-bottom: 4px;
  }

  /* Taskbar / dock - left side, Ubuntu style */
  #taskbar {
    position: absolute;
    top: 36px;
    left: 8px;
    bottom: 8px;
    width: 58px;
    background: rgba(15, 8, 20, 0.75);
    border-radius: 14px;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 10px 0;
    gap: 10px;
    z-index: 4000;
    box-shadow: 0 4px 20px rgba(0,0,0,0.4);
  }
  .launcher {
    width: 42px;
    height: 42px;
    border-radius: 10px;
    background: rgba(255,255,255,0.08);
    border: none;
    color: #fff;
    font-size: 20px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.15s, transform 0.1s;
  }
  .launcher:hover { background: rgba(255,255,255,0.2); transform: scale(1.05); }
  .launcher:active { transform: scale(0.96); }

  /* Windows */
  .win {
    position: absolute;
    min-width: 360px;
    min-height: 240px;
    width: 560px;
    height: 400px;
    background: #2d2d2d;
    border-radius: 8px;
    box-shadow: 0 20px 60px rgba(0,0,0,0.5);
    display: none;
    flex-direction: column;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,0.08);
    z-index: 100;
  }
  .win.open { display: flex; }
  .win-titlebar {
    height: 34px;
    background: #383838;
    display: flex;
    align-items: center;
    padding: 0 8px;
    cursor: move;
    flex-shrink: 0;
    border-bottom: 1px solid rgba(0,0,0,0.3);
  }
  .win-title {
    flex: 1;
    font-size: 13px;
    color: #ddd;
    padding-left: 6px;
  }
  .win-controls { display: flex; gap: 6px; }
  .win-btn {
    width: 14px;
    height: 14px;
    border-radius: 50%;
    border: none;
    cursor: pointer;
  }
  .win-close { background: #ff5f57; }
  .win-min { background: #febc2e; }
  .win-max { background: #28c840; }
  .win-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: #262626;
    color: #eee;
  }

  /* Files app */
  #files-toolbar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 10px;
    background: #303030;
    border-bottom: 1px solid #1c1c1c;
    flex-shrink: 0;
  }
  #files-up {
    background: #444;
    border: none;
    color: #fff;
    padding: 4px 10px;
    border-radius: 4px;
    cursor: pointer;
    font-size: 13px;
  }
  #files-up:hover { background: #555; }
  #files-path {
    font-family: monospace;
    font-size: 13px;
    color: #cdeaff;
    background: #1e1e1e;
    padding: 4px 8px;
    border-radius: 4px;
    flex: 1;
  }
  #files-listing {
    flex: 1;
    overflow: auto;
    padding: 14px;
    display: flex;
    flex-wrap: wrap;
    align-content: flex-start;
    gap: 4px;
  }
  .fs-item {
    width: 90px;
    text-align: center;
    padding: 10px 4px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 12px;
    word-break: break-word;
  }
  .fs-item:hover { background: rgba(255,255,255,0.08); }
  .fs-item.selected { background: rgba(80,150,255,0.35); }
  .fs-item .fs-glyph {
    font-size: 30px;
    display: block;
    margin-bottom: 4px;
  }

  /* Notepad app */
  #notepad-toolbar {
    display: flex;
    align-items: stretch;
    background: #303030;
    border-bottom: 1px solid #1c1c1c;
    flex-shrink: 0;
  }
  #tabs {
    display: flex;
    overflow-x: auto;
    flex: 1;
  }
  .tab {
    padding: 8px 14px;
    font-size: 12px;
    background: #333;
    color: #ccc;
    border-right: 1px solid #1c1c1c;
    cursor: pointer;
    white-space: nowrap;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-shrink: 0;
  }
  .tab.active { background: #262626; color: #fff; }
  .tab-close {
    background: none;
    border: none;
    color: #999;
    cursor: pointer;
    font-size: 12px;
    line-height: 1;
    padding: 0 2px;
  }
  .tab-close:hover { color: #fff; }
  #new-tab {
    background: #303030;
    border: none;
    color: #ccc;
    font-size: 18px;
    width: 34px;
    cursor: pointer;
    flex-shrink: 0;
  }
  #new-tab:hover { background: #3d3d3d; }
  #editor {
    flex: 1;
    width: 100%;
    background: #1e1e1e;
    color: #eee;
    border: none;
    outline: none;
    resize: none;
    padding: 12px;
    font-family: "Consolas", monospace;
    font-size: 14px;
    line-height: 1.5;
  }
</style>
</head>
<body>

<div id="desktop">
  <div id="top-bar">Activities &nbsp;•&nbsp; Ubuntu Desktop &nbsp;•&nbsp; <span id="clock"></span></div>

  <div id="desktop-icons">
    <div class="desk-icon" id="icon-files" title="Files">
      <span class="glyph">🗂️</span>Files
    </div>
    <div class="desk-icon" id="icon-notepad" title="Notepad">
      <span class="glyph">📝</span>Notepad
    </div>
  </div>

  <div id="taskbar">
    <button class="launcher" id="open-files" title="Files">🗂️</button>
    <button class="launcher" id="open-notepad" title="Notepad">📝</button>
  </div>

  <!-- Files Window -->
  <div class="win" id="files-window" style="top:70px; left:110px;">
    <div class="win-titlebar" data-drag-for="files-window">
      <div class="win-controls">
        <button class="win-btn win-close" data-target="files-window"></button>
        <button class="win-btn win-min"></button>
        <button class="win-btn win-max"></button>
      </div>
      <div class="win-title">Files</div>
    </div>
    <div class="win-body">
      <div id="files-toolbar">
        <button id="files-up">&#8593; Up</button>
        <div id="files-path">/</div>
      </div>
      <div id="files-listing"></div>
    </div>
  </div>

  <!-- Notepad Window -->
  <div class="win" id="notepad-window" style="top:110px; left:220px;">
    <div class="win-titlebar" data-drag-for="notepad-window">
      <div class="win-controls">
        <button class="win-btn win-close" data-target="notepad-window"></button>
        <button class="win-btn win-min"></button>
        <button class="win-btn win-max"></button>
      </div>
      <div class="win-title">Notepad</div>
    </div>
    <div class="win-body">
      <div id="notepad-toolbar">
        <div id="tabs"></div>
        <button id="new-tab" title="New Tab">+</button>
      </div>
      <textarea id="editor" spellcheck="false"></textarea>
    </div>
  </div>
</div>

<script>
(function () {
  "use strict";

  /* ---------- Clock ---------- */
  function updateClock() {
    var d = new Date();
    var h = d.getHours().toString().padStart(2, "0");
    var m = d.getMinutes().toString().padStart(2, "0");
    document.getElementById("clock").textContent = h + ":" + m;
  }
  updateClock();
  setInterval(updateClock, 1000 * 30);

  /* ---------- Window management ---------- */
  function showWindow(id) {
    var w = document.getElementById(id);
    w.classList.add("open");
    bringToFront(w);
  }
  function hideWindow(id) {
    document.getElementById(id).classList.remove("open");
  }

  var zTop = 100;
  function bringToFront(win) {
    zTop += 1;
    win.style.zIndex = zTop;
  }

  document.querySelectorAll(".win").forEach(function (win) {
    win.addEventListener("mousedown", function () { bringToFront(win); });
  });

  document.getElementById("open-files").addEventListener("click", function () {
    showWindow("files-window");
  });
  document.getElementById("open-notepad").addEventListener("click", function () {
    showWindow("notepad-window");
  });
  document.getElementById("icon-files").addEventListener("dblclick", function () {
    showWindow("files-window");
  });
  document.getElementById("icon-notepad").addEventListener("dblclick", function () {
    showWindow("notepad-window");
  });

  document.querySelectorAll(".win-close").forEach(function (btn) {
    btn.addEventListener("click", function (e) {
      e.stopPropagation();
      hideWindow(btn.getAttribute("data-target"));
    });
  });

  /* Dragging windows by their titlebar */
  document.querySelectorAll("[data-drag-for]").forEach(function (bar) {
    var winId = bar.getAttribute("data-drag-for");
    var win = document.getElementById(winId);
    var dragging = false;
    var offX = 0, offY = 0;

    bar.addEventListener("mousedown", function (e) {
      if (e.target.classList.contains("win-btn")) return;
      dragging = true;
      var rect = win.getBoundingClientRect();
      offX = e.clientX - rect.left;
      offY = e.clientY - rect.top;
      bringToFront(win);
      e.preventDefault();
    });

    window.addEventListener("mousemove", function (e) {
      if (!dragging) return;
      var deskRect = document.getElementById("desktop").getBoundingClientRect();
      var newLeft = e.clientX - offX - deskRect.left;
      var newTop = e.clientY - offY - deskRect.top;
      newLeft = Math.max(0, Math.min(newLeft, deskRect.width - 100));
      newTop = Math.max(0, Math.min(newTop, deskRect.height - 40));
      win.style.left = newLeft + "px";
      win.style.top = newTop + "px";
    });

    window.addEventListener("mouseup", function () { dragging = false; });
  });

  /* ---------- Files app ---------- */
  var FS = {
    name: "/",
    type: "folder",
    children: [
      {
        name: "bin", type: "folder", children: [
          { name: "bash", type: "file" },
          { name: "ls", type: "file" },
          { name: "cat", type: "file" }
        ]
      },
      {
        name: "etc", type: "folder", children: [
          { name: "hostname", type: "file" },
          { name: "passwd", type: "file" },
          { name: "fstab", type: "file" }
        ]
      },
      {
        name: "home", type: "folder", children: [
          {
            name: "user", type: "folder", children: [
              {
                name: "Documents", type: "folder", children: [
                  { name: "resume.txt", type: "file" },
                  { name: "notes.md", type: "file" }
                ]
              },
              {
                name: "Downloads", type: "folder", children: [
                  { name: "installer.deb", type: "file" }
                ]
              },
              {
                name: "Pictures", type: "folder", children: [
                  { name: "wallpaper.png", type: "file" },
                  { name: "vacation.jpg", type: "file" }
                ]
              },
              { name: ".bashrc", type: "file" },
              { name: "readme.txt", type: "file" }
            ]
          }
        ]
      },
      {
        name: "usr", type: "folder", children: [
          {
            name: "lib", type: "folder", children: [
              { name: "libc.so", type: "file" }
            ]
          },
          {
            name: "share", type: "folder", children: [
              { name: "applications", type: "folder", children: [] }
            ]
          }
        ]
      },
      {
        name: "var", type: "folder", children: [
          {
            name: "log", type: "folder", children: [
              { name: "syslog", type: "file" },
              { name: "auth.log", type: "file" }
            ]
          },
          { name: "www", type: "folder", children: [] }
        ]
      }
    ]
  };

  var currentPathParts = []; // e.g. ["home","user","Documents"]

  function resolvePath(parts) {
    var node = FS;
    for (var i = 0; i < parts.length; i++) {
      var found = null;
      if (node.children) {
        for (var j = 0; j < node.children.length; j++) {
          if (node.children[j].name === parts[i]) {
            found = node.children[j];
            break;
          }
        }
      }
      if (!found) return null;
      node = found;
    }
    return node;
  }

  function renderPath() {
    var pathStr = "/" + currentPathParts.join("/");
    document.getElementById("files-path").textContent = pathStr;
  }

  function renderListing() {
    var node = resolvePath(currentPathParts);
    var listing = document.getElementById("files-listing");
    listing.innerHTML = "";
    if (!node || !node.children) return;
    node.children.forEach(function (child) {
      var el = document.createElement("div");
      el.className = "fs-item";
      el.setAttribute("data-name", child.name);
      el.setAttribute("data-type", child.type);
      var glyph = document.createElement("span");
      glyph.className = "fs-glyph";
      glyph.textContent = child.type === "folder" ? "📁" : "📄";
      var label = document.createElement("div");
      label.textContent = child.name;
      el.appendChild(glyph);
      el.appendChild(label);

      el.addEventListener("click", function () {
        listing.querySelectorAll(".fs-item").forEach(function (i) { i.classList.remove("selected"); });
        el.classList.add("selected");
      });

      el.addEventListener("dblclick", function () {
        if (child.type === "folder") {
          currentPathParts.push(child.name);
          renderPath();
          renderListing();
        }
      });

      listing.appendChild(el);
    });
  }

  document.getElementById("files-up").addEventListener("click", function () {
    if (currentPathParts.length > 0) {
      currentPathParts.pop();
      renderPath();
      renderListing();
    }
  });

  renderPath();
  renderListing();

  /* ---------- Notepad app ---------- */
  var STORAGE_KEY = "desktop-notepad-tabs";
  var tabs = [];
  var activeTabId = null;
  var idCounter = 0;

  function loadTabs() {
    var raw = null;
    try {
      raw = localStorage.getItem(STORAGE_KEY);
    } catch (e) {
      raw = null;
    }
    if (raw) {
      try {
        var parsed = JSON.parse(raw);
        if (parsed && Array.isArray(parsed.tabs) && parsed.tabs.length > 0) {
          tabs = parsed.tabs;
          activeTabId = parsed.activeTabId;
          idCounter = parsed.idCounter || tabs.length;
          if (!tabs.some(function (t) { return t.id === activeTabId; })) {
            activeTabId = tabs[0].id;
          }
          return;
        }
      } catch (e) { /* fall through to default */ }
    }
    var id = ++idCounter;
    tabs = [{ id: id, title: "Untitled 1", content: "" }];
    activeTabId = id;
  }

  function saveTabs() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({
        tabs: tabs,
        activeTabId: activeTabId,
        idCounter: idCounter
      }));
    } catch (e) { /* storage unavailable, ignore */ }
  }

  function renderTabs() {
    var tabsEl = document.getElementById("tabs");
    tabsEl.innerHTML = "";
    tabs.forEach(function (tab) {
      var tabEl = document.createElement("div");
      tabEl.className = "tab" + (tab.id === activeTabId ? " active" : "");
      tabEl.setAttribute("data-id", tab.id);

      var titleEl = document.createElement("span");
      titleEl.textContent = tab.title;
      tabEl.appendChild(titleEl);

      var closeEl = document.createElement("button");
      closeEl.className = "tab-close";
      closeEl.textContent = "×";
      closeEl.addEventListener("click", function (e) {
        e.stopPropagation();
        closeTab(tab.id);
      });
      tabEl.appendChild(closeEl);

      tabEl.addEventListener("click", function () {
        activeTabId = tab.id;
        renderTabs();
        renderEditor();
        saveTabs();
      });

      tabsEl.appendChild(tabEl);
    });
  }

  function renderEditor() {
    var editor = document.getElementById("editor");
    var tab = tabs.find(function (t) { return t.id === activeTabId; });
    editor.value = tab ? tab.content : "";
  }

  function closeTab(id) {
    var idx = tabs.findIndex(function (t) { return t.id === id; });
    if (idx === -1) return;
    tabs.splice(idx, 1);
    if (tabs.length === 0) {
      var newId = ++idCounter;
      tabs.push({ id: newId, title: "Untitled " + newId, content: "" });
      activeTabId = newId;
    } else if (activeTabId === id) {
      var newIdx = Math.max(0, idx - 1);
      activeTabId = tabs[newIdx].id;
    }
    renderTabs();
    renderEditor();
    saveTabs();
  }

  document.getElementById("new-tab").addEventListener("click", function () {
    var id = ++idCounter;
    tabs.push({ id: id, title: "Untitled " + id, content: "" });
    activeTabId = id;
    renderTabs();
    renderEditor();
    saveTabs();
  });

  document.getElementById("editor").addEventListener("input", function (e) {
    var tab = tabs.find(function (t) { return t.id === activeTabId; });
    if (tab) {
      tab.content = e.target.value;
      saveTabs();
    }
  });

  loadTabs();
  renderTabs();
  renderEditor();

})();
</script>
</body>
</html>
